import java.util.*;class Solution{public int calculate(String s){Deque<Integer>st=new ArrayDeque<>();int n=0;char op='+';for(int i=0;i<=s.length();i++){char c=i<s.length()?s.charAt(i):0;if(Character.isDigit(c))n=n*10+c-'0';if((!Character.isDigit(c)&&c!=' ')||c==0){if(op=='+')st.push(n);else if(op=='-')st.push(-n);else if(op=='*')st.push(st.pop()*n);else st.push(st.pop()/n);op=c;n=0;}}int r=0;for(int x:st)r+=x;return r;}}
